// A throwaway lease authority for the virtual device, generated by the pinned Gate's
// development-authority script in a private directory; no existing key is ever read.
import { execFile } from 'node:child_process';
import { readFile, writeFile } from 'node:fs/promises';
import { join, resolve } from 'node:path';
import { promisify } from 'node:util';
import { authorityCall, signAttempt } from '../fixed-usb-qualification/authority.mjs';
import { nonce } from '../fixed-usb-qualification/contract.mjs';

const run = promisify(execFile);
/** A synthetic endpoint the virtual device never dials. */
export const SYNTHETIC_STRATUM = Object.freeze({ endpoint: 'stratum+tcp://127.0.0.1:3333/', username: 'synthetic', password: 'synthetic' });

/** The signer sees only what it needs to run Bun. */
const environment = () => ({ PATH: process.env.PATH, LANG: 'C', LC_ALL: 'C' });

/**
 * Generates the authority under `root` (outside every worktree) and writes the virtual
 * deployment trust: the firmware's update authority, so the real signed capability still
 * verifies, beside the throwaway work-lease authority that signs this run's leases.
 */
export async function throwawayAuthority({ gateRoot, root, firmwareTrustPath }) {
  const directory = join(root, 'authority');
  await run('bun', [resolve(gateRoot, 'scripts/worker-development-authority.ts'), 'init', '--directory', directory],
    { cwd: gateRoot, env: environment(), timeout: 30000, maxBuffer: 4096 });
  const generated = JSON.parse(await readFile(join(directory, 'trust.json'), 'utf8'));
  const firmware = JSON.parse(await readFile(firmwareTrustPath, 'utf8'));
  const trust = { ...firmware, workLeaseAuthority: generated.workLeaseAuthority };
  const trustPath = join(root, 'virtual-deployment-trust.json');
  await writeFile(trustPath, `${JSON.stringify(trust)}\n`, { flag: 'wx', mode: 0o600 });
  return { directory, trustPath };
}

/** Signs one operation through the Gate script; signer diagnostics never reach evidence. */
export function authoritySigner({ gateRoot, directory }) {
  return (operation, input) => authorityCall(gateRoot, directory, `sign-${operation}`, input, 'bun',
    { maybeEnvironment: environment() });
}

/**
 * Signs a normal qualification attempt (ordinal 1 on a fresh virtual board) and its
 * renewals with the production composition, bound to one control session.
 */
export function signVirtualAttempt({ challengeId, binding, sign }) {
  const attempt = { schema: 'worker-qualification-attempt-v1', id: nonce(), ordinal: 1, purpose: 'normal', maximumActiveMilliseconds: 180000 };
  return signAttempt({ attempt, challengeId, binding, stratum: SYNTHETIC_STRATUM, sign });
}
